package com.scriptles.cabinet.profile.controller;
import com.scriptles.cabinet.profile.dto.*; import com.scriptles.cabinet.profile.entity.CatalogOrganization; import com.scriptles.cabinet.profile.enums.OrganizationType; import com.scriptles.cabinet.profile.repository.CatalogOrganizationRepository; import com.scriptles.cabinet.profile.service.ProfileService; import com.scriptles.cabinet.security.AuthenticatedUser; import com.scriptles.cabinet.user.repository.UserRepository; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/v1/moderation/hq") @RequiredArgsConstructor public class HQBootstrapController { private final CatalogOrganizationRepository organizations; private final ProfileService profiles; private final com.scriptles.cabinet.profile.service.HQOperatorService operators;
 @GetMapping public com.scriptles.cabinet.common.api.PageResponse<HQAdminSummaryResponse> list(@AuthenticationPrincipal AuthenticatedUser actor,@RequestParam(defaultValue="") String query,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){if(!actor.admin()) throw new com.scriptles.cabinet.common.api.ApiException(HttpStatus.FORBIDDEN,"HQ_FORBIDDEN","Apenas administradores podem listar HQs"); return profiles.adminHQs(query,page,size);}
 @PutMapping("/{profileId}") public ProfileResponse update(@AuthenticationPrincipal AuthenticatedUser actor,@PathVariable java.util.UUID profileId,@Valid @RequestBody HQUpdateRequest request){return profiles.updateHQ(profileId,request,actor.id());}
 @PostMapping @org.springframework.transaction.annotation.Transactional public ProfileResponse create(@AuthenticationPrincipal AuthenticatedUser actor,@Valid @RequestBody CreateHQRequest request){if(!actor.admin()) throw new com.scriptles.cabinet.common.api.ApiException(HttpStatus.FORBIDDEN,"HQ_FORBIDDEN","Apenas administradores podem criar HQs"); if(request.operatorEmail()==null||request.operatorName()==null||request.operatorPassword()==null) throw new com.scriptles.cabinet.common.api.ApiException(HttpStatus.BAD_REQUEST,"HQ_OPERATOR_REQUIRED","Informe as credenciais do responsável pela HQ"); CatalogOrganization o=organizations.findByPrimarySourceAndPrimaryExternalId(request.source(),request.externalId()).orElseGet(CatalogOrganization::new);o.setType(type(request.type()));o.setCanonicalName(request.name());o.setPrimarySource(request.source());o.setPrimaryExternalId(request.externalId());o.setWebsiteUrl(request.websiteUrl());o.setCountryCode(request.countryCode());o.setLogoUrl(request.logoUrl());o.setDescription(request.description());o=organizations.save(o);var existing=profiles.existingHQ(o.getPrimarySource(),o.getPrimaryExternalId());if(existing.isPresent()) return profiles.find(existing.get().getHandle(),actor.id());var p=profiles.createOfficialHQ(o,request.type(),request.handle());operators.create(p.getId(),new com.scriptles.cabinet.profile.service.HQOperatorService.OperatorInput(request.operatorEmail(),request.operatorName(),request.operatorPassword(),com.scriptles.cabinet.profile.enums.HQMemberRole.OWNER));return profiles.find(p.getHandle(),actor.id());}
 @PostMapping("/{profileId}/operators") public com.scriptles.cabinet.profile.service.HQOperatorService.OperatorView addOperator(@AuthenticationPrincipal AuthenticatedUser actor,@PathVariable java.util.UUID profileId,@RequestBody com.scriptles.cabinet.profile.service.HQOperatorService.OperatorInput input){if(!actor.admin()) throw new com.scriptles.cabinet.common.api.ApiException(HttpStatus.FORBIDDEN,"HQ_FORBIDDEN","Apenas administradores podem conceder acesso");return operators.create(profileId,input);}
 private OrganizationType type(com.scriptles.cabinet.profile.enums.HQType type){return switch(type){case FILM_STUDIO->OrganizationType.FILM_STUDIO;case PRODUCTION_COMPANY->OrganizationType.PRODUCTION_COMPANY;case TV_NETWORK->OrganizationType.NETWORK;case DISTRIBUTOR->OrganizationType.DISTRIBUTOR;case RECORD_LABEL->OrganizationType.RECORD_LABEL;case MUSIC_DISTRIBUTOR->OrganizationType.MUSIC_DISTRIBUTOR;default->OrganizationType.OTHER;};}}
